-- Rifts World Book 36: Sovietski - Cyberlink and cybernetics, printed 159-163.
-- 22 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~383-sovietski-cyberlink.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- PRINTED 159-163 RUN FROM THE CYBERLINK ENTRY TO STABILIZING ANCHORS, where
-- Bionic Weapons and Tools begins (a later row's). Cyber-Nano-Robot Repair
-- Systems on p.159 shipped in ~382. Cyber-Traction Spikes (p.160) is only a
-- pointer to Cyber-Crampons. That leaves 39 systems; 22 are rows here.
--
-- THE CYBERLINK IS A NEW ROW, NOT THE HELD ONE. The book calls its CVI updated
-- and revised. Against Warlords of Russia (the held
-- cyberlink-vehicle-interfacing, same 250,000 credits) it adds +5% to every
-- skill used to run a small vehicle, halves piloting penalties for a pilot with
-- the vehicle's Piloting skill, and requires a Cyberlink system in the vehicle
-- as well as the cyborg. The held row is left as it is.
--
-- FIVE MORE DIFFER FROM A HELD ROW AND ARE NEW ROWS, the held ones untouched:
-- Wide-Angle Vision gives +1 Perception where Warlords of Russia gives +1
-- initiative; the Epidermic Analyzer reads temperature in 30 seconds, not one
-- minute; Internal Energy Supply prices the nuclear generator at 1-2 million
-- (Japan: 1 million) and cuts its life to 8 years in heavy combat. The
-- Medical Sensor Hand costs 60,000 (Triax: 20,000) and the Stabilizing Anchors
-- print bonuses and penalties the New West anchors do not.
--
-- SEVENTEEN REPRINT A HELD ROW WITH THE SAME FIGURES and are left out:
-- Cyber-Jet Nodes, Depth Gauge & Alarm, Spectra-Eye, Super-Telescopic Eye,
-- Third Eye, Gromeko FFI Computer, Gills, Head Collar & Hood, Hydraulic Leg
-- Boosters, Laser Scalpel Finger, Pulse & Pressure Detector, Stethoscope
-- Feature, Multi-System Eye Socket, Panorama Cluster Lens, Psionic
-- Electro-Magnetic Dampers, Radar Sensor and Schematic Sensor Hand.
--
-- A cost printed as a range or by size stores the lower figure, with all of
-- them in cost_note. Hardened Circuits is a 20% surcharge and stores no cost.
-- The manifest lists no substituted digits or glyph damage on p.159-163; the
-- cache was checked against a 110 dpi render of p.160.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('sovietski-cyberlink-vehicle-interface', 'Cyberlink Vehicle Interface Piloting System (CVI), Revised', 'rifts', 'cybernetics', NULL, 250000, '250,000 credits (the price in Russia)', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The Sovietski''s updated CVI. A partial or full conversion cyborg fitted with it can join his mind to any Russian vehicle that carries its own Cyberlink system (most Sovietski and Warlord vehicles do); both sides need the system, and an ordinary finger or head jack is not enough. Linked, he feels the vehicle''s speed, heading, engine state, faults and damage, and runs its steering, sensors, radio, optics and weapons by thought, hands and eyes left free. While linked he can do nothing but pilot and use the vehicle; breaking the link to do anything else ends every bonus at once. Full control works only on small one- or two-man and simple vehicles (bikes, cars, hovercycles, snowmobiles, rocket bikes, flying wings, construction machines, and Russian craft like the Landflier, Bush Bike, War Chariot, Steppe Motorcycle, Assault Hoversled and Wingrider); on a tank, aircraft, ship or giant robot it reaches one system only, such as piloting plus one weapon, one weapon station, communications and sensors, or the medical system. Bonuses while linked: +1 initiative, +1 to strike when ramming and +1 with built-in weapons, +1 to dodge, +1 melee action that must use the vehicle. On a small vehicle every skill tied to running it gains +5%, or +10% to a Piloting skill the cyborg has for it. With that Piloting skill, penalties for combat maneuvers, evasive action, stunts and crashes are halved. Without it he still pilots any CVI vehicle at a flat 45%, which never improves and gets no penalty reduction. He can push top speed up by 1% per I.Q. point for three minutes per M.E. point. Revises the Warlords of Russia system, which prints neither the +5% skill bonus nor the halved penalties.', 'Rifts World Book 36: Sovietski p.159', NULL),
  ('sovietski-cyber-skates', 'Cyber-Skates', 'rifts', 'cybernetics', NULL, 3000, '3,000 credits a pair for Light Machines; 4,500 for Heavy and Superheavy Machines. The lower figure is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A sturdy skate blade on pistons housed in each foot. The pistons drive the blade out and act as small shock absorbers under the cyborg''s weight. Extending a skate takes one melee action apiece, though both drop together when falling, leaping or flying. Deployed, they skate like ordinary ice skates; in-line roller wheels can be fitted in their place. A cyborg with Cyber-Crampons in his feet can have no other foot enhancement.', 'Rifts World Book 36: Sovietski p.159-160', NULL),
  ('sovietski-cyber-skis', 'Cyber-Skis', 'rifts', 'cybernetics', NULL, 5000, '5,000 credits a pair for Light Machines; 8,000 for Heavy and Superheavy Machines. The lower figure is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Folding skis stored in a compartment at the back of each lower leg. Raising a leg lets the ski swing down beneath the foot, unfold and lock; the cyborg then shifts his weight and does the other. Each takes one melee action, or both at once when falling, leaping or flying. They work as normal downhill or cross-country skis under the skill. Heavy and Superheavy Machines get longer, wider skis. Their shape rules out waterskiing, though water skis could be built the same way.', 'Rifts World Book 36: Sovietski p.160', NULL),
  ('sovietski-cyber-snowshoes', 'Cyber-Snowshoes', 'rifts', 'cybernetics', NULL, 3000, '3,000 credits a pair, Light Machines (and partial conversions) only', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A fan of M.D.C. mesh on a light frame folded into each leg, which slides out and spreads under the foot. It spreads a partial cyborg''s or Light Machine''s weight so that in deep snow (2 ft/0.6 m or more) he moves at only -30% Spd, with dodge -2 and roll with impact -2. Useless for Heavy and Superheavy Machines, which sink to the knee or deeper in such snow and plod: Spd -70%, -1 melee attack unless standing still, dodge -3, roll with impact -3, other combat maneuvers -1.', 'Rifts World Book 36: Sovietski p.160', NULL),
  ('sovietski-digital-camera-finger', 'Digital Camera Finger', 'rifts', 'cybernetics', NULL, 3500, '3,500 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An upgrade of the microfilm finger camera that saves high-resolution images to a memory chip instead, up to 2,000 of them. Pictures go to another device wirelessly or by cable through a port in the side of the finger. The finger stays flexible; the price is the drawback.', 'Rifts World Book 36: Sovietski p.160', NULL),
  ('sovietski-directional-sound-amplification-finger', 'Directional Sound Amplification Finger', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits', NULL, 0, '300 feet (91 m) for a quiet 20-decibel conversation', NULL, NULL, NULL, NULL, NULL, 'An eavesdropping finger, often paired with the video finger camera: aimed at a target, it relays the sound as if heard with the cyborg''s own ears, picking up a quiet conversation at 300 ft (91 m). While it is in use he hears nothing but where the finger points. Penalties in use: -3 initiative, -2 to parry and dodge.', 'Rifts World Book 36: Sovietski p.160', NULL),
  ('sovietski-multi-optic-eye', 'Eye: Multi-Optic Eye', 'rifts', 'cybernetics', NULL, 55000, '55,000-60,000 credits for one eye; 100,000 for a pair fitted at the same time. The lower figure is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'One mechanical eye holding several optic systems: telescopic (4-8x30, range 6,000 ft/1,829 m), macro lens (2x to 8x, range 3 ft/0.9 m), passive nightvision and thermo-imaging (each 2,000 ft/610 m), glare-reducing light filters, and a targeting display whose crosshairs give +1 to strike with any ranged weapon. The bonus is the same with one Multi-Optic eye or two.', 'Rifts World Book 36: Sovietski p.160', NULL),
  ('sovietski-optic-nerve-video-implant', 'Eye: Optic Nerve Video Implant', 'rifts', 'cybernetics', NULL, 35000, '35,000 credits, high for the delicacy of the surgery', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A sensor set directly on the optic nerve so that video transmissions play inside the recipient''s sight, the visual counterpart of the Headjack''s ear implant; together the two let him watch and hear audio-visual messages secretly. Tried on the blind, it restores sight: 1-45% fully, 46-80% to 65%, 81-95% to 40%, 96-00% to only 10% (legally blind). Sometimes illegal for ordinary citizens; illegal in the Coalition States.', 'Rifts World Book 36: Sovietski p.160', NULL),
  ('sovietski-targeting-sight', 'Eye: Targeting Sight', 'rifts', 'cybernetics', NULL, 4000, '4,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An add-on for any mechanical eye that lays crosshairs over the view to fix on a target: +1 to strike with any weapon. Two eyes with it still give only +1. Sometimes illegal for ordinary citizens; illegal in the Coalition States.', 'Rifts World Book 36: Sovietski p.160-161', NULL),
  ('sovietski-wide-angle-vision', 'Eye: Wide-Angle Vision', 'rifts', 'cybernetics', NULL, 60000, '60,000 credits', NULL, 0, '1,000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'A wide-angle lens giving the cyborg 180 degrees of peripheral sight, so no ambush or surprise attack can come at him from the flanks. Bonuses: +1 to Perception Rolls and +1 to dodge. Can be built into other optic or multi-optic bionic eyes. It is plainly mechanical and sticks out of the socket: P.B. -10%. The Warlords of Russia version gives +1 initiative where this one gives +1 Perception.', 'Rifts World Book 36: Sovietski p.161', NULL),
  ('sovietski-hardened-circuits', 'Hardened Circuits', 'rifts', 'cybernetics', NULL, NULL, 'An extra 20% of the listed cost of the bionic or cybernetic system it is added to; no fixed price.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An option for any cybernetic or bionic system: its circuitry is shielded against electromagnetic scramblers and EMP.', 'Rifts World Book 36: Sovietski p.161', NULL),
  ('sovietski-internal-energy-supply', 'Internal Energy Supply', 'rifts', 'cybernetics', NULL, 500000, '500,000 credits for the battery; 1-2 million for an internal nuclear generator like those in power armor and robots. The lower figure is stored.', NULL, 0, NULL, 'Battery: 500 blasts; nuclear generator: effectively unlimited for about 11 years (8 under heavy combat)', NULL, NULL, NULL, NULL, 'A dedicated power source built into the torso of a full conversion ''Borg, feeding only his built-in weapons, tools and power-hungry cybernetics. The battery powers 500 standard blasts from any of his energy weapons, forearm and shoulder blasters included. The nuclear generator lasts about 11 years of effectively unlimited fire, cut to about 8 by the hard fighting typical for Sovietski and Warlord combat cyborgs. Prices the generator at 1-2 million where the Japan book gives 1 million.', 'Rifts World Book 36: Sovietski p.161', NULL),
  ('sovietski-medical-blood-analysis-tox-screen', 'Medical: Blood Analysis/Tox-Screen', 'rifts', 'cybernetics', NULL, 30000, '30,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Sensors in the hand (a finger or part of the palm) that check a sample against 60 common poisons and blood irregularities, such as insulin or sugar out of range, cholesterol, cell counts or poison, when the blood touches them. Also tells whether a sample is human, animal, D-Bee or of unknown origin.', 'Rifts World Book 36: Sovietski p.161', NULL),
  ('sovietski-medical-epidermic-analyzer', 'Medical: Epidermic Analyzer', 'rifts', 'cybernetics', NULL, 35000, '35,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Molecular analyzers in the hand that gauge salt, sugar and strong enzymes or chemicals from a touch of skin or sweat, and take body temperature with 30 seconds of contact. Times the temperature reading at 30 seconds where Warlords of Russia gives one minute.', 'Rifts World Book 36: Sovietski p.161', NULL),
  ('sovietski-medical-epidermal-temperature-gauge', 'Medical: Epidermal Temperature Gauge', 'rifts', 'cybernetics', NULL, 1000, '1,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The hand, or one finger, reads a patient''s temperature on contact with the neck, head or armpit.', 'Rifts World Book 36: Sovietski p.161', NULL),
  ('sovietski-medical-sensor-hand', 'Medical: Sensor Hand', 'rifts', 'cybernetics', NULL, 60000, '60,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A sensor hand built for medical care rather than general utility, with room for up to 14 features, each bought on its own. It comes with every Medical feature listed here plus 1D4 other cybernetic systems. Priced at 60,000 where the Triax and the NGR medical sensor hand costs 20,000.', 'Rifts World Book 36: Sovietski p.162', NULL),
  ('sovietski-neural-aggression-modulator-control', 'Neural Aggression Modulator Control (NAMC)', 'rifts', 'cybernetics', NULL, 420000, '420,000 credits. Unique to the Sovietski, rare and experimental.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A paired system, part in a human cyborg handler and part in the brains of up to four cyborg animals, from the Sovietski''s experiments with bionic beasts. The handler''s voice rewards the animal through its brain''s pleasure center, while tones and commands rouse or soothe aggression or trigger pain, so he can hold it steady under fire, override flight, send it through fire or loose it at full fury. Each animal is tuned to its handler''s voice, scent and other traits and takes him as its leader or mate; it obeys him and one backup only. Commands go by voice or radio, each module on its own signature and frequency, so a captured animal cannot be turned. Animals are hard to retune to a new handler and dangerous when one fails and runs wild. Suits even wild stock such as mountain lions, bears and eagles. Mostly given to Special Forces, scouts and animal handlers. The implants descend from pre-Cataclysm M.O.M./Crazy technology. Animal bonuses: +1 attack per melee, +1 initiative, +1 to strike and dodge.', 'Rifts World Book 36: Sovietski p.162', NULL),
  ('sovietski-oxygen-storage-cell', 'Oxygen Storage Cell (Lung Implant)', 'rifts', 'cybernetics', NULL, 60000, '60,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A microprocessor-run chemical cell that banks oxygen from normal breathing and releases it into the lungs when air runs short, letting the character go up to 30 minutes without breathing. Recharging takes about an hour of ordinary breathing between uses.', 'Rifts World Book 36: Sovietski p.162', NULL),
  ('sovietski-secret-compartments', 'Secret Compartments', 'rifts', 'cybernetics', NULL, 1000, '1,000 credits each small, 2,500 each medium, 4,000 each large. The small price is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Hidden hollows built into a cyborg''s legs and chest. The biggest is about 12 in (30.5 cm) long and 4-6 in (10-15 cm) deep, most are half that or less, and the smallest hold a few credit cards, coins, lock picks or bugs; large ones take tools, grenades and small handguns. As a guide, each leg and the chest fit two medium or one large, or up to six small; an arm fits one small each in the forearm and upper arm, and only if it carries no weapon system.', 'Rifts World Book 36: Sovietski p.162-163', NULL),
  ('sovietski-sensor-hand-standard', 'Sensor Hand (Standard)', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits as a mechanical hand or 33,000 as a Bio-System hand, plus receivers: ear receiver 1,000 (can join other ear implants), wristband monitor 250-500, pocket receiver-monitor 100. The lower figure is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A replacement for a lost hand, either a plain mechanical one or a Bio-System hand with living tissue, that works like the original and also carries heat, motion, radiation and radar detectors, a gyro-compass and a clock calendar (each as the single sensor implant). Readings go to a tiny receiver on the eardrum, a watch-like wristband with audio and an LCD, or a calculator-sized hand-held unit; several receivers can share it, and cybernetic eyes (not Bio-System eyes) can show the data too.', 'Rifts World Book 36: Sovietski p.163', NULL),
  ('sovietski-speedometer', 'Speedometer', 'rifts', 'cybernetics', NULL, 400, '400 credits; 1,200 for the advanced version that shows a running readout on a HUD in a bionic eye, a wrist unit or a plug-in monitor.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A cheap, simple sensor that tells the character how fast he is going, on foot or riding in a vehicle.', 'Rifts World Book 36: Sovietski p.163', NULL),
  ('sovietski-stabilizing-anchors', 'Stabilizing Anchors (Triax Tech)', 'rifts', 'cybernetics', NULL, 5000, '5,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Russian take on a New German Republic design, after the Glitter Boy''s: spikes about 8 in (20 cm) long fire from the lower legs into the ground to hold the cyborg in place, for construction, climbing, or steadying cyborgs carrying heavy rail guns and light artillery. The Sovietski has no Boom Gun, and the rumor that the anchors let a cyborg fire one is false. Deploying takes one action and retracting another. While deployed: +2 to resist knockdown, dodge -2, roll with impact -2. The New West stabilizing anchors print no bonuses or penalties.', 'Rifts World Book 36: Sovietski p.163', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 22 gear rows are in' AS assertion, count(*) AS got, 22 AS want
  FROM gear WHERE slug IN ('sovietski-cyberlink-vehicle-interface', 'sovietski-cyber-skates', 'sovietski-cyber-skis', 'sovietski-cyber-snowshoes', 'sovietski-digital-camera-finger', 'sovietski-directional-sound-amplification-finger', 'sovietski-multi-optic-eye', 'sovietski-optic-nerve-video-implant', 'sovietski-targeting-sight', 'sovietski-wide-angle-vision', 'sovietski-hardened-circuits', 'sovietski-internal-energy-supply', 'sovietski-medical-blood-analysis-tox-screen', 'sovietski-medical-epidermic-analyzer', 'sovietski-medical-epidermal-temperature-gauge', 'sovietski-medical-sensor-hand', 'sovietski-neural-aggression-modulator-control', 'sovietski-oxygen-storage-cell', 'sovietski-secret-compartments', 'sovietski-sensor-hand-standard', 'sovietski-speedometer', 'sovietski-stabilizing-anchors') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~383-sovietski-cyberlink.sql');
